<div class="table-wrap"><table><thead><tr><th>Trip</th><th>Owner</th><th>Destination</th><th>Dates</th><th>Action</th></tr></thead><tbody><?php foreach ($trips as $trip): ?><tr><td><?php echo h($trip['name']); ?></td><td><?php echo h($trip['owner']); ?></td><td><?php echo h((string)$trip['destination']); ?></td><td><?php echo h($trip['start_date'] . ' to ' . $trip['end_date']); ?></td><td><form method="post"><input type="hidden" name="action" value="delete_trip"><input type="hidden" name="id" value="<?php echo $trip['id']; ?>"><button class="danger" type="submit">Remove</button></form></td></tr><?php endforeach; ?></tbody></table></div>
